export const SCHEMA_TQL = "# The vehicle's engineering model in TypeDB 3.\n#\n# Three independent ways of organising the same components:\n#   physical   assembly-membership   where a component sits (wheel end > chassis > vehicle)\n#   functional system-membership     what it does (braking, propulsion, automated driving...); a component\n#                                    can take part in several systems\n#   behaviour  connection, dependency (function to function, with fallbacks) and control-loop: how components\n#              are joined, what each function relies on to\n#              work, and which controllers, sensors and actuators work together\n# Plus the link from each component to the 3D object that draws it (visual-representation).\n#\n# All specifications are design targets for an original concept vehicle, not measured data.\n\ndefine\n\n# ---- Identity and description ----------------------------------------------------------------------------\n\nattribute component-id, value string @regex(\"^[a-z0-9]+(-[a-z0-9]+)*$\");   # stable; never renamed\nattribute assembly-id, value string @regex(\"^[a-z0-9]+(-[a-z0-9]+)*$\");\nattribute system-id, value string @regex(\"^[a-z0-9]+(-[a-z0-9]+)*$\");\nattribute asset-name, value string;\nattribute node-key, value string;\nattribute name, value string;\nattribute description, value string;\n\n# ---- Engineering properties (only on the components they apply to) ------------------------------------\n\nattribute material-name, value string;\nattribute size-designation, value string;           # e.g. tyre \"275/45 R22\", wheel \"22 x 9.5J\"\nattribute diameter-mm, value double;\nattribute thickness-mm, value double;\nattribute piston-count, value integer;\nattribute peak-power-kw, value double;\nattribute rated-power-kw, value double;\nattribute peak-torque-nm, value double;\nattribute gear-ratio, value double;\nattribute tooth-count, value integer;\nattribute nominal-voltage-v, value double;\nattribute energy-capacity-kwh, value double;\nattribute sensing-range-m, value double;\n\n# ---- Kinds of connection --------------------------------------------------------------------------------\n\nattribute joint-type, value string @values(\"bolted\", \"splined\", \"press-fit\", \"bearing\", \"ball-joint\", \"bushed\", \"welded\", \"bonded\", \"clipped\", \"threaded\", \"seated\", \"meshed\", \"hinged\", \"universal-joint\");\nattribute voltage-class, value string @values(\"high-voltage\", \"low-voltage\");\nattribute network, value string @values(\"CAN FD\", \"automotive Ethernet\", \"hard-wired signal\");\nattribute fluid, value string @values(\"brake fluid\", \"coolant\", \"refrigerant\", \"oil\");\nattribute dependency-kind, value string @values(\"power\", \"torque\", \"control\", \"data\", \"hydraulic\", \"cooling\", \"lubrication\", \"support\");\nattribute loss-effect, value string @values(\"lost\", \"degraded\");\nattribute degradation-effect, value string @values(\"lost\", \"degraded\");\nattribute function-name, value string;\n\n# ---- Components: a type hierarchy, so questions can be asked at any level (\"every sensor\") ------------------\n\nentity component @abstract,\n  owns component-id @key, owns name, owns description, owns material-name,\n  plays assembly-membership:member @card(1..1),\n  plays system-membership:member,\n  plays connection:endpoint,\n  plays dependency:dependent, plays dependency:provider, plays fallback:backup,\n  plays visual-representation:represented @card(1..1);\n\nentity body-component @abstract, sub component;\nentity body-panel sub body-component;\nentity glazing sub body-component;\nentity lighting-unit sub body-component;\nentity structural-member sub body-component;\nentity trim-part sub body-component;\nentity interior-component sub component;\n\nentity chassis-component @abstract, sub component;\nentity wheel sub chassis-component, owns size-designation, owns diameter-mm;\nentity tyre sub chassis-component, owns size-designation, owns diameter-mm;\nentity brake-component sub chassis-component;\nentity brake-disc sub brake-component, owns diameter-mm, owns thickness-mm;\nentity brake-caliper sub brake-component, owns piston-count, plays control-loop:actuator;\nentity brake-pad sub brake-component;\nentity wheel-end-component sub chassis-component;         # hub, bearing, knuckle\nentity suspension-component sub chassis-component;\nentity subframe-mount sub chassis-component;           # rubber mounts carrying a subframe on the body\nentity steering-component sub chassis-component;\nentity fastener sub component;\nentity driver-control sub component;                 # pedals and other direct driver inputs\n\nentity powertrain-component @abstract, sub component;\nentity electric-motor sub powertrain-component, owns peak-power-kw, owns peak-torque-nm, owns nominal-voltage-v,\n  plays control-loop:actuator;\nentity motor-component sub powertrain-component;\nentity gearbox sub powertrain-component, owns gear-ratio;\nentity gearbox-component sub powertrain-component;\nentity gear sub gearbox-component, owns tooth-count;      # gears and shafts with integral gear teeth\nentity park-lock sub gearbox-component, plays control-loop:actuator;\nentity axle-disconnect sub gearbox-component, plays control-loop:actuator;\nentity mount sub powertrain-component;                    # rubber mounts carrying a drive unit on its subframe\nentity drive-shaft sub powertrain-component;\nentity inverter sub powertrain-component, owns peak-power-kw, owns nominal-voltage-v;\nentity inverter-component sub powertrain-component;\n\nentity electrical-component @abstract, sub component;\nentity battery-module sub electrical-component, owns energy-capacity-kwh, owns nominal-voltage-v;\nentity battery-component sub electrical-component;\nentity low-voltage-battery sub electrical-component, owns energy-capacity-kwh, owns nominal-voltage-v;\nentity power-electronics sub electrical-component, owns rated-power-kw, owns nominal-voltage-v;\nentity wiring-harness sub electrical-component;\nentity connector sub electrical-component;\nentity contactor sub electrical-component, plays control-loop:actuator;   # main contactors, pre-charge relay\nentity fuse sub electrical-component;                     # pack fuse, service disconnect, 12 V fuse box\n\nentity sensor @abstract, sub component, owns sensing-range-m, plays control-loop:sensor;\nentity camera sub sensor;\nentity radar sub sensor;\nentity lidar sub sensor;\nentity gnss-receiver sub sensor;\nentity wheel-speed-sensor sub sensor;\nentity position-sensor sub sensor;                      # motor resolvers\nentity current-sensor sub sensor;\nentity torque-sensor sub sensor;                        # steering torque on the pinion shaft\nentity cell-monitor sub sensor;                          # battery module monitoring boards\n\nentity control-unit sub component, plays control-loop:controller;\nentity compute-unit sub control-unit;\nentity actuator sub component, plays control-loop:actuator;\nentity thermal-component sub component;\n\n# ---- Physical structure: assemblies and sub-assemblies ---------------------------------------------------\n\nentity assembly,\n  owns assembly-id @key, owns name, owns description,\n  plays assembly-membership:assembly,\n  plays assembly-membership:member @card(0..1);\n\n# Every component and every assembly except the vehicle itself sits in exactly one assembly.\nrelation assembly-membership,\n  relates assembly,\n  relates member;\n\n# ---- Function: systems and subsystems -------------------------------------------------------------------\n\nentity system,\n  owns system-id @key, owns name, owns description,\n  plays system-membership:system,\n  plays system-membership:member,\n  plays control-loop:controlled-system;\n\nrelation system-membership,\n  relates system,\n  relates member;\n\n# ---- Behaviour ------------------------------------------------------------------------------------------\n\n# A physical joint or line between two components. Undirected: both ends play \"endpoint\".\nrelation connection @abstract, relates endpoint @card(2..2), owns description;\nrelation mechanical-connection sub connection, owns joint-type;\nrelation power-connection sub connection, owns voltage-class;\nrelation data-connection sub connection, owns network;\nrelation fluid-connection sub connection, owns fluid;\n\n# What a part does: \"drive torque\", \"brake pressure\", \"anti-lock braking\"... Shared across components. Failure\n# states belong to (component, function) pairs, so a failure can take one function and leave others.\nentity vehicle-function,\n  owns function-name @key,\n  plays dependency:affected-function, plays dependency:required-function;\n\n# \"The dependent's affected function needs the provider's required function.\" Directed, one of three families.\n# loss-effect: what happens to the affected function if the required function is lost.\n# degradation-effect (optional): what happens if the required function is only degraded; absent = nothing.\nrelation dependency @abstract,\n  relates dependent @card(1..1),\n  relates affected-function @card(1..1),\n  relates provider @card(1..1),\n  relates required-function @card(1..1),\n  owns dependency-kind,\n  owns loss-effect @card(1..1),\n  owns degradation-effect,\n  owns description,\n  plays fallback:protected;\nrelation physical-dependency sub dependency;        # load paths, mechanical support, torque transmission\nrelation operational-dependency sub dependency;     # energy and working media: power, cooling, hydraulic pressure\nrelation control-dependency sub dependency;         # commands and sensor information\n\n# If the provider's function is lost but the backup still works, the dependent is degraded, not lost\n# (for example the brake pedal pushing the master cylinder without the booster).\nrelation fallback,\n  relates protected @card(1..1),\n  relates backup @card(1..1),\n  owns description;\n\n# A closed loop: a controller reads sensors and commands actuators to govern a system.\nrelation control-loop,\n  relates controller @card(1..1),\n  relates sensor @card(0..),\n  relates actuator @card(1..),\n  relates controlled-system @card(1..1),\n  owns name, owns description;\n\n# ---- The link to 3D geometry ----------------------------------------------------------------------------\n\n# A visual asset is a model file (or \"procedural\": built in the browser). The node key names the object in\n# that file. Node keys are only visual keys: the component id is the identity.\nentity visual-asset, owns asset-name @key, plays visual-representation:asset;\n\nrelation visual-representation,\n  relates represented,\n  relates asset,\n  owns node-key;\n";

export const FUNCTIONS_TQL = "# Functions: named, reusable query logic stored in the database. The recursive ones walk relationships\n# to any depth, which is how \"multi-step\" questions are answered.\n\ndefine\n\n# Every assembly above $a, at any depth (sub-assembly > assembly > ... > vehicle).\nfun assembly_ancestors($a: assembly) -> { assembly }:\n  match\n    { assembly-membership (assembly: $parent, member: $a); }\n    or { let $mid in assembly_ancestors($a); assembly-membership (assembly: $parent, member: $mid); };\n  return { $parent };\n\n# Every component inside $a, including those in its sub-assemblies.\nfun assembly_components($a: assembly) -> { component }:\n  match\n    { assembly-membership (assembly: $a, member: $c); $c isa component; }\n    or { assembly-membership (assembly: $a, member: $sub); $sub isa assembly;\n         let $c in assembly_components($sub); };\n  return { $c };\n\n# Every system that $s is part of, at any depth.\nfun system_ancestors($s: system) -> { system }:\n  match\n    { system-membership (system: $parent, member: $s); }\n    or { let $mid in system_ancestors($s); system-membership (system: $parent, member: $mid); };\n  return { $parent };\n\n# Every component taking part in $s, directly or through its subsystems.\nfun system_components($s: system) -> { component }:\n  match\n    { system-membership (system: $s, member: $c); $c isa component; }\n    or { system-membership (system: $s, member: $sub); $sub isa system;\n         let $c in system_components($sub); };\n  return { $c };\n\n# Failure impact, function by function (docs/dependency-semantics.md, C1). When $start fails, all its functions\n# are lost; each dependency then applies its effects. Two functions call each other:\n#   lost_steps      the dependent's function is LOST\n#   degraded_steps  the dependent's function is DEGRADED\n# Each returns the steps (provider, its function, dependent, its function). A function reached both ways is\n# lost (callers apply that). Fallbacks: a backup counts unless it is the failed part itself, or the failure takes\n# away one of the backup's functions through dependencies that have no fallback of their own (hard_losses below:\n# a shared cause, such as the charge port feeding both DC charging and its backup, the on-board charger, or the\n# 12 V supply behind both the park lock and the electric parking brake). The tests compare every failure with an\n# exact oracle, which checks this rule is sufficient for the data.\n\n# Functions the failure of $start takes away for certain: through \"lost\" dependencies that no fallback covers.\n# It never consults fallbacks, so lost_steps and degraded_steps can use it inside a negation.\nfun hard_losses($start: component) -> { component, vehicle-function }:\n  match\n    $d isa dependency (provider: $p, required-function: $g, dependent: $c, affected-function: $f), has loss-effect \"lost\";\n    not { fallback (protected: $d); };\n    { $p is $start; } or { let $p, $g in hard_losses($start); };\n  return { $c, $f };\n\n# Lost when the required function is lost and nothing takes over, or when it is degraded and the dependency\n# says that degradation is enough to lose the function.\nfun lost_steps($start: component) -> { component, vehicle-function, component, vehicle-function }:\n  match\n    $d isa dependency (provider: $p, required-function: $g, dependent: $c, affected-function: $f);\n    {\n      $d has loss-effect \"lost\";\n      not { fallback (protected: $d, backup: $b); not { $b is $start; };\n            not { let $b, $bf in hard_losses($start); }; };\n      { $p is $start; } or { let $p0, $g0, $p, $g in lost_steps($start); };\n    } or {\n      $d has degradation-effect \"lost\";\n      let $p1, $g1, $p, $g in degraded_steps($start);\n    };\n  return { $p, $g, $c, $f };\n\n# Degraded when the required function is lost but the dependency only degrades (or a backup takes over),\n# or when the required function is degraded and the dependency passes that on.\nfun degraded_steps($start: component) -> { component, vehicle-function, component, vehicle-function }:\n  match\n    $d isa dependency (provider: $p, required-function: $g, dependent: $c, affected-function: $f);\n    {\n      { $d has loss-effect \"degraded\"; }\n      or { $d has loss-effect \"lost\"; fallback (protected: $d, backup: $b); not { $b is $start; };\n           not { let $b, $bf in hard_losses($start); }; };\n      { $p is $start; } or { let $p0, $g0, $p, $g in lost_steps($start); };\n    } or {\n      $d has degradation-effect \"degraded\";\n      let $p1, $g1, $p, $g in degraded_steps($start);\n    };\n  return { $p, $g, $c, $f };\n\n# The reverse walk: every (provider, function) that $end's functions rely on, directly or indirectly.\n# Returns each step: dependent, its function, provider, the function it supplies.\nfun requirement_steps($end: component) -> { component, vehicle-function, component, vehicle-function }:\n  match\n    dependency (dependent: $c, affected-function: $f, provider: $p, required-function: $g);\n    { $c is $end; } or { let $c0, $f0, $c, $f in requirement_steps($end); };\n  return { $c, $f, $p, $g };\n";

